              if (dayTitle) {
                const dayMatch = dayTitle.textContent.match(/第(\d+)天/);
                if (dayMatch && parseInt(dayMatch[1]) !== parseInt(dayNum)) {
                  section.style.display = 'none';
                }
              }
            });

            // 核心修复：强制替换地图为图片，不会空白
            if (mapImageData) {
              const mapContainerClone = clonedDoc.querySelector(`.map-container[data-day="${dayNum}"]`);
              if (mapContainerClone) {
                mapContainerClone.innerHTML = '';
                const img = clonedDoc.createElement('img');
                img.src = mapImageData;
                img.style.width = '100%';
                img.style.height = '400px';
                img.style.objectFit = 'cover';
                img.style.display = 'block';
                mapContainerClone.appendChild(img);
              }
            }
          },
          ignoreElements: el => {
            return el.classList.contains('no-print') || el.classList.contains('card-actions') || el.classList.contains('expand-btn');
          }
        });

        // 5. 生成PDF，A4分页适配
        const imgData = canvas.toDataURL('image/png');
        const pdf = new jsPDF('p', 'mm', 'a4');
        const imgWidth = 210;
        const pageHeight = 297;
        const imgHeight = canvas.height * imgWidth / canvas.width;
        let heightLeft = imgHeight;
        let position = 0;
        pdf.addImage(imgData, 'PNG', 0, position, imgWidth, imgHeight);
        heightLeft -= pageHeight;
        while (heightLeft >= 0) {
          position = heightLeft - imgHeight;
          pdf.addPage();
          pdf.addImage(imgData, 'PNG', 0, position, imgWidth, imgHeight);
          heightLeft -= pageHeight;
        }

        // 6. 下载PDF
        const currentDayData = this.routeDetail.itinerary.find(d => d.dayNum.toString() === dayNum);
        const fileName = currentDayData ? `第${dayNum}天行程-${this.routeDetail.recommendationName || '贵阳旅游行程'}.pdf` : `${this.routeDetail.recommendationName || '贵阳旅游行程'}.pdf`;
        pdf.save(fileName);
        this.$message.success(`第${dayNum}天行程PDF导出成功！`);
      } catch (error) {
        console.error('导出失败:', error);
        this.$message.error('导出失败: ' + (error.message || '请重试'));
      } finally {
        loading.close();
        this.exporting = false;
      }
    },
    // 初始化导出模式的地图
    initExportMap(dayNum, containerEl) {
      if (!window.AMap || !containerEl) {
        console.warn(`第${dayNum}天地图初始化失败：缺少必要参数`);
        return;
      }

      // 销毁旧地图实例
      if (this.maps[dayNum]) {
        this.maps[dayNum].destroy();
      }

      // 获取该天的景点数据
      const day = this.routeDetail.itinerary.find(d => d.dayNum === dayNum);
      if (!day) {
        console.warn(`第${dayNum}天数据不存在`);
        return;
      }
      const attractions = this.getDayAttractions(day);
      if (attractions.length === 0) {
        console.warn(`第${dayNum}天没有景点坐标数据`);
        return;
      }
      try {
        // 创建地图实例
        const map = new AMap.Map(containerEl, {
          zoom: 12,
          center: [attractions[0].longitude, attractions[0].latitude],
          mapStyle: 'amap://styles/light',
          resizeEnable: true
        });

        // 缓存地图实例
        this.$set(this.maps, dayNum, map);

        // 提取坐标点
        const path = attractions.map(p => [p.longitude, p.latitude]);

        // 绘制路线连线
        const polyline = new AMap.Polyline({
          path: path,
          strokeColor: '#FF7A2F',
          strokeWeight: 4,
          strokeStyle: 'solid',
          lineJoin: 'round',
          lineCap: 'round'
        });
        map.add(polyline);

        // 添加标记点
        attractions.forEach((point, index) => {
          let offsetX = 0;
          let offsetY = 0;
          if (index > 0) {
            const prevPoint = attractions[index - 1];
            const distance = Math.sqrt(Math.pow(point.longitude - prevPoint.longitude, 2) + Math.pow(point.latitude - prevPoint.latitude, 2));
            if (distance < 0.002) {
              offsetX = (index % 2 === 0 ? 1 : -1) * 0.00015;
              offsetY = (index % 2 === 0 ? 1 : -1) * 0.00015;
            }
          }
          const markerContent = `
            <div style="
              background: #FF7A2F;
              color: white;
              width: 28px;
              height: 28px;
              border-radius: 50%;
              display: flex;
              align-items: center;
              justify-content: center;
              font-size: 14px;
              font-weight: bold;
              border: 3px solid white;
              box-shadow: 0 2px 6px rgba(0,0,0,0.3);
            ">${point.index}</div>
          `;
          const marker = new AMap.Marker({
            position: [point.longitude + offsetX, point.latitude + offsetY],
            content: markerContent,
            offset: new AMap.Pixel(-14, -14)
          });
          map.add(marker);
        });

        // 调整地图视野
        map.setFitView();
        console.log(`✅ 第${dayNum}天导出地图初始化成功,共${attractions.length}个点位`);
      } catch (error) {
        console.error(`第${dayNum}天导出地图初始化失败:`, error);
      }
    }
  }
};
